from pathlib import Path
import re,json,difflib
W=Path(__file__).resolve().parents[2];D=Path(__file__).resolve().parent
IDS=['p33g','p33h','p33i','p34','p34a','p34b','p34c','p34d','p34e','p34f','p34g','p34h','p34i','p34j','p34l','p35','p35a-und-35b','p36','p36a','p37']
revisions={}
def change(i,old,new):revisions.setdefault(i,[]).append((old,new))
change('p33g','Nummer 2 wirkt in die Gegenrichtung.','Die Verordnung bedarf des gesetzlich bestimmten Ressorteinvernehmens und der Zustimmung des Bundesrates. Nummer 1 betrifft nur andere Spiele nach § 33d, nicht schon jede Geräteaufstellung nach § 33c. Nummer 2 wirkt in die Gegenrichtung.')
change('p33i','Absatz 2 verbindet persönliche Versagungsgründe mit Raum- und Standorteignung sowie dem Schutz vor Jugendgefährdung, übermäßiger Spieltriebsausnutzung und unzumutbaren Auswirkungen.','Absatz 2 verbindet persönliche Versagungsgründe mit Raum- und Standorteignung sowie dem Schutz vor Jugendgefährdung, übermäßiger Spieltriebsausnutzung und unzumutbaren Auswirkungen. Nummer 1 verweist gezielt auf § 33c Abs. 2 Nr. 1 und § 33d Abs. 3, nicht pauschal auf sämtliche Aufstelleranforderungen. Die polizeilichen Raumanforderungen der Nummer 2 und die prognostischen Gefährdungen der Nummer 3 sind selbständige Versagungsgründe. Nicht erst ein eingetretener Schaden löst die Prüfung aus. Das Erfordernis einer notwendigen Schutzmaßnahme begrenzt sowohl Befristung als auch Auflagen.')
change('p34','Absatz 4 verbietet den gewerbsmäßigen Sachankauf mit Rückkaufsrecht und wirkt damit gegen die Umgehung des Pfandleihschutzes durch eine andere Vertragsbezeichnung.','Absatz 4 verbietet den gewerbsmäßigen Sachankauf mit Rückkaufsrecht und wirkt damit gegen die Umgehung des Pfandleihschutzes durch eine andere Vertragsbezeichnung. Eine Pfandleiherlaubnis hebt dieses Verbot nicht auf. Ob ein Rückkaufsrecht gewährt wird, erfordert die Prüfung der tatsächlichen Abreden; eine bloße spätere Erwerbschance ist damit nicht ohne Weiteres identisch.')
change('p34','Erlaubnis, Vertragsgestaltung und konkrete Verwertung bilden drei unterschiedliche Kontrollpunkte.','Erlaubnis, Vertragsgestaltung und konkrete Verwertung bilden drei unterschiedliche Kontrollpunkte. Wird ein Pfand etwa 2026 verwertet, läuft die Dreijahresfrist des Absatzes 3 erst nach Ende dieses Jahres; eine rechtzeitige Anmeldung durch einen Empfangsberechtigten ist gesondert festzuhalten.\n\nBeim Fahrzeugmodell „sale and rent back“ darf nicht jeder zivilrechtliche Unwirksamkeitsbefund als Entscheidung über Absatz 4 zitiert werden. [BGH, Urteil vom 16. November 2022 – VIII ZR 436/21, Rn. 29 und 35–53](cases/bgh-viiizr436-21.md), ließ dessen Verletzung ausdrücklich offen und stützte die Unwirksamkeit im konkreten Fall auf Sittenwidrigkeit. Die Beleggrenze betrifft gerade den Unterschied zwischen der Begründung der Vorinstanz und dem tragenden Grund des BGH.')
change('p34a','Die Regelbeispiele mangelnder Zuverlässigkeit haben unterschiedliche Zeiträume und Schwellen; eine bloße Erwähnung in einer polizeilichen Information ist nicht mit einer rechtskräftigen Verurteilung gleichzusetzen.','Die Regelbeispiele mangelnder Zuverlässigkeit haben unterschiedliche Zeiträume und Schwellen: Bei den bezeichneten Vereins- und Parteimitgliedschaften sind zehn Jahre seit deren Beendigung, bei verfassungsfeindlichen Bestrebungen fünf Jahre maßgeblich. Das strafrechtliche Regelbeispiel verlangt die benannten Delikte und Sanktionen; bei Geldstrafen sind mindestens 90 Tagessätze oder mindestens zwei geringere Geldstrafen genannt. Es sind sowohl der Bezug zur Antragstellung als auch die seit Rechtskraft der letzten Verurteilung verstrichene Zeit zu prüfen. Eine bloße Erwähnung in einer polizeilichen Information ist nicht mit einer rechtskräftigen Verurteilung gleichzusetzen. Auch die Regelannahme ersetzt nicht die Prüfung des konkreten Falls.')
change('p34a','Bei Flüchtlingsunterkünften und Großveranstaltungen ist für diese Qualifikationsanforderung die leitende Funktion relevant,','Die Sachkundeliste umfasst Kontrollgänge in öffentlichen oder tatsächlich öffentlich zugänglichen Bereichen, Ladendiebstahlsschutz und den Einlassbereich gastgewerblicher Diskotheken sowie die beiden leitenden Bewachungsaufgaben. Bei Flüchtlingsunterkünften und zugangsgeschützten Großveranstaltungen ist für diese Qualifikationsanforderung die leitende Funktion relevant,')
change('p34a','Absatz 1b ermöglicht Nachberichte und begrenzt die weitere Speicherung durch besondere Löschungsfristen.','Absatz 1b ermöglicht Nachberichte. Die zur Zuverlässigkeitsprüfung verarbeiteten Daten sind spätestens nach fünf Jahren durch die Verfassungsschutzbehörde zu löschen. Für die in Absatz 1 genannten Personen gilt bei Kenntnis der bezeichneten negativen oder beendenden Erlaubnisentscheidungen eine frühere Sechsmonatsfrist. Der entsprechende Verweis erfasst auch die beteiligten Polizeibehörden. Diese Löschungsregeln sind von den eigenständigen Registerregeln des § 11b zu trennen.')
change('p34b','Letztere verlangt besondere Sachkunde, betrifft natürliche Personen und kann auch angestellten Versteigerern oder für bestimmte Versteigerungsarten erteilt werden.','Letztere ist auf Antrag bei besonderer Sachkunde vorzunehmen, betrifft natürliche Personen und gilt entsprechend für angestellte Versteigerer. Bei der Beschränkung auf bestimmte Versteigerungsarten kommt zusätzlich der im Gesetz genannte Bedarf an solchen Leistungen hinzu.')
change('p34b','Die Regelannahmen sind am konkreten Tatbestand und am relevanten Zeitraum zu prüfen.','Beim strafrechtlichen Regelbeispiel sind die bezeichneten Verurteilungen innerhalb der letzten fünf Jahre vor Antragstellung und die verlangte Freiheitsstrafe maßgeblich; der Deliktskatalog allein genügt nicht. Insolvenz und die bezeichneten Verzeichniseinträge begründen die weitere Regelannahme ungeordneter Vermögensverhältnisse. Beide Regelannahmen sind am konkreten Tatbestand zu prüfen.')
change('p34b','Absatz 10 nimmt die benannten amtlichen, spezialgesetzlichen und ausschließlich geschäftlichen Bieterkreise aus.','Absatz 10 nimmt die benannten amtlichen und spezialgesetzlichen Verkäufe sowie Versteigerungen mit einem besonders abgegrenzten Bieterkreis aus: Jeder zugelassene Bieter muss Waren der angebotenen Art für seinen Geschäftsbetrieb ersteigern wollen. Die bloße Bezeichnung als Unternehmerauktion oder der Ausschluss privater Zuschauer genügt nicht.')
change('p34d','Sondervergütungsverbot und begrenzte rechtliche Beratungsbefugnis des Maklers sind jeweils eigenständige Grenzen.','Das Sondervergütungsverbot ist von der Rechtsberatungsbefugnis des Maklers zu trennen: Eine gesondert vergütete rechtliche Beratung über Vereinbarung, Änderung oder Prüfung von Versicherungsverträgen deckt die Maklererlaubnis grundsätzlich für Dritte, die keine Verbraucher sind; ausdrücklich einbezogen sind Beschäftigte eines vom Makler beratenen Unternehmens. Daraus folgt keine allgemeine Erlaubnis zur entgeltlichen Verbraucherrechtsberatung.')
change('p34d','Er darf nur vom Auftraggeber vergütet werden und muss die dort bezeichneten Zuwendungen vermeiden oder deren Auskehrung veranlassen.','Er darf nur vom Auftraggeber vergütet werden. Sind mehrere Versicherungen gleich geeignet, ist vorrangig die ohne Versichererzuwendung erhältliche anzubieten; bei Vermittlung eines Vertrags mit eingerechneter Zuwendung hat der Berater unverzüglich deren Auskehrung durch den Versicherer an den Versicherungsnehmer zu veranlassen. Dies ist kein Recht des Beraters, die Zuwendung zunächst als eigenes Honorar zu behalten.')
change('p34d','Die 600-Euro-Jahresgrenze und die besondere 200-Euro-Grenze bei kurzen Dienstleistungen sind keine allgemeine Bagatellgrenze für beliebigen Vertrieb; die sachlichen Voraussetzungen müssen zusammen vorliegen.','Nummer 1 verlangt kumulativ Nebentätigkeit, Zusatzleistungscharakter und eines der bezeichneten Waren-, Dienstleistungs- oder Reiserisiken. Die 600-Euro-Grenze bezieht sich auf die zeitanteilig auf Jahresbasis berechnete Prämie; alternativ gelten 200 Euro je Person bei einer Dienstleistungsdauer von höchstens drei Monaten. Nummer 2 betrifft die enge Absicherung von Bausparkassenforderungen über Kollektivverträge. Die eigenständige 500-Euro-Jahresgrenze der Nummer 3 betrifft Restschuldversicherungen als Zusatzleistung im Zusammenhang mit Darlehens- und Leasingverträgen. Keine dieser Grenzen schafft eine allgemeine Bagatellausnahme für beliebigen Versicherungsvertrieb.')
change('p34d','Die Ausnahmen und die Möglichkeit eines delegierten Unternehmernachweises sind nicht auf alle Personen übertragbar.','Die Weiterbildungsausnahme für bestimmte gebundene Zusatzleistungsvermittler ist gesondert zu prüfen. Die Befreiung nach Absatz 6 beseitigt die dort ebenfalls geltende Personalprüfung nicht, führt aber nicht bereits als solche zur Einbeziehung in die gesetzliche 15-Stunden-Liste. Ein delegierter Unternehmernachweis ist für eine selbst vermittelnde oder leitend verantwortliche natürliche Person ausgeschlossen. Die Behörde kann die Beschäftigung bei mangelnder Sachkunde oder Zuverlässigkeit untersagen.')
change('p34d','Absatz 11 erlaubt die Veröffentlichung bestimmter unanfechtbarer Entscheidungen mit Verhältnismäßigkeits-, Ermittlungs- und Löschungsgrenzen.','Absatz 11 erlaubt die Veröffentlichung bestimmter unanfechtbarer Entscheidungen mit Verhältnismäßigkeits-, Ermittlungs- und Löschungsgrenzen. Regelmäßig ist nach fünf Jahren zu löschen; personenbezogene Daten schon vorher, sobald ihre Veröffentlichung nicht mehr erforderlich ist. Die durch BGBl. 2026 I Nr. 33 vorgesehene zusätzliche ESAP-Bereitstellung gilt nach dessen Art. 64 Abs. 8 erst ab 10. Januar 2030 und gehört nicht zum Stichtagsbestand.')
change('p34g','Auch die bekannte Aufzeichnung telefonischer und elektronischer Beratung,','Auch die Aufzeichnung telefonischer Beratungsgespräche und elektronischer Kundenkommunikation in Kenntnis der Kunden,')
change('p34g','§ 34g nennt etwa keine eigenständige tägliche Aufbewahrungsfrist für sämtliche Kommunikationsformen.','§ 34g nennt etwa keine einheitliche Aufbewahrungsdauer für sämtliche Kommunikationsformen. Absatz 1 verpflichtet zur Regelung, Absatz 2 eröffnet demgegenüber zusätzliche Regelungsoptionen; daraus folgt keine unterschiedslose unmittelbare Anwendung jedes dort aufgezählten Instruments auf jeden Vermittler.')
change('p34i','Absatz 6 erfasst Sachkunde und Zuverlässigkeit unmittelbar Mitwirkender sowie leitend Verantwortlicher und erstreckt bestimmte Pflichten auf inländische Zweigniederlassungen europäischer Anbieter.','Absatz 6 erfasst Sachkunde und Zuverlässigkeit der bei Vermittlung oder Beratung mitwirkenden sowie der dafür leitend verantwortlichen Beschäftigten. Anders als die Registerpflicht nach Absatz 8 beschränkt der erste Satz seinen Wortlaut nicht auf „unmittelbar“ Mitwirkende. Auch die Beschäftigungsuntersagung ist von der Aufhebung der Unternehmenserlaubnis zu unterscheiden. Beide Regeln gelten entsprechend für die in Absatz 4 bezeichneten Anbieter, wenn sie im Inland über eine Zweigniederlassung tätig werden.')
change('p34l','Umgekehrt darf er eine künftig erforderliche Qualifikation nicht allein deshalb ignorieren, weil die Ermächtigung noch keine eigene unmittelbare Weiterbildungspflicht formuliert.','Für die Vorbereitung der späteren Tätigkeit sind die bereits verkündeten künftigen Zugangsvoraussetzungen und deren Übergangsregeln gesondert zu ermitteln; aus der Ermächtigung allein ergibt sich noch keine konkrete heutige Weiterbildungsstundenzahl.')
change('p35','Die Untersagung kann teilweise genügen. Eine Ausdehnung auf andere Gewerbe oder Leitungs- und Vertretungsfunktionen setzt voraus, dass die Tatsachen auch diese Tätigkeiten tragen; sie folgt nicht automatisch aus jeder Untersagung.','Sind diese Voraussetzungen erfüllt, ist die erforderliche Untersagung nach Satz 1 gebunden; eine teilweise Untersagung kann genügen. Die Erweiterung nach Satz 2 steht demgegenüber im Ermessen. Sie setzt gewerbeübergreifende Unzuverlässigkeit und die Erforderlichkeit der Erstreckung voraus und folgt nicht automatisch aus jeder Untersagung.')
change('p35','Er enthält keine allgemeine Gleichsetzung von Strafurteil und Gewerbeprognose.','Die Bindung betrifft Sachverhalt, Schuldfrage und die ausdrücklich bezeichnete Beurteilung einer künftigen erheblichen rechtswidrigen Tat samt Untersagungsbedarf; die Erstreckung nach Absatz 1 Satz 2 bleibt unberührt. Schweigt ein Strafurteil zur beruflichen Zukunft, ersetzt dieses Schweigen keine gewerberechtliche Prognose. Es besteht keine allgemeine Gleichsetzung von Strafurteil und Gewerbeprognose.')
change('p35','Sie verlangt Antrag und Tatsachen für wiedererlangte Zuverlässigkeit. Vor Ablauf eines Jahres nach Durchführung braucht es besondere Gründe. Absätze 7 und 7a regeln Zuständigkeit und eigenständiges Vorgehen gegen Vertretungs- oder Leitungspersonen. Absatz 8 gibt besonderen Untersagungs- und Erlaubnisaufhebungsregeln grundsätzlich Vorrang, enthält aber ausdrückliche Rückausnahmen. Absatz 9 erweitert die Anwendung auf die dort genannten Bereiche.','Sie verlangt einen schriftlichen oder elektronischen Antrag und Tatsachen für wiedererlangte Zuverlässigkeit; dann besteht ein Anspruch auf Wiedergestattung. Vor Ablauf eines Jahres nach Durchführung braucht es zusätzlich besondere Gründe. Die Jahresfrist allein stellt die Ausübungsbefugnis nicht wieder her. Absatz 7 knüpft vorrangig an die vorhandene oder beabsichtigte Niederlassung, sonst an den Ausübungsort an und ergänzt die Vollstreckungszuständigkeit. Absatz 7a ermöglicht ein eigenständiges Verfahren gegen Vertretungs- oder Leitungspersonen; verwiesen wird auf Absatz 1 und Absätze 3–7, nicht auf die Stellvertretergestattung des Absatzes 2.\n\nAbsatz 8 lässt besondere, an Unzuverlässigkeit anknüpfende Schließungs- und Zulassungsaufhebungsregeln grundsätzlich vorgehen. Die Rückausnahmen betreffen Vertretungs- und Leitungsfunktionen sowie strafgerichtliche Untersagungen oder Betriebsschließungen. Absatz 9 erweitert die Anwendung auch auf nur mitgliederbezogene Genossenschaftsbetriebe und die bezeichneten Arzneimittel-, Los- und Wettannahmetätigkeiten; die Ausnahmen in § 6 dürfen diesen ausdrücklichen Anwendungsbefehl nicht verdecken.')
change('p36','Der Bedarf bezieht sich auf Sachverständigenleistungen des Gebiets; er darf nicht ohne Weiteres mit dem Schutz bereits bestellter Personen vor Konkurrenz verwechselt werden.','Der Bedarf bezieht sich auf Sachverständigenleistungen des Gebiets, nicht auf eine offene Stelle für einen zusätzlichen Gutachter. Der Status darf nicht zum Schutz bereits bestellter Personen vor Konkurrenz durch eine individuelle Bedarfsprüfung verknappt werden.')
change('p36','Absatz 4a macht die Verhältnismäßigkeitsprüfung anhand der Anlage verbindlich.','Absatz 4a macht für die in Absatz 4 Satz 3 erfassten neuen oder geänderten Berufsregeln die Verhältnismäßigkeitsprüfung anhand der Anlage verbindlich. Die Norm erfasst damit nicht unterschiedslos jede unveränderte Satzungsbestimmung oder jeden Einzelbestellungsakt.')
change('p36','Beispiel: Eine Kammer will für ein Sachgebiet zusätzliche Qualifikationsnachweise einführen.','[BVerwG, Urteil vom 1. Februar 2012 – 8 C 24.11, Rn. 17, 21–22 und 26–28](cases/bverwg-8c24-11.md), verwarf eine generelle satzungsmäßige Höchstaltersgrenze. Im betroffenen EDV-Sachgebiet war die persönliche Leistungsfähigkeit individuell zu prüfen. Daraus folgt weder eine Befreiung von der Sachkundeprüfung noch ein Urteil über jede sicherheitsbezogene Altersanforderung. Die heutige zusätzliche Prüfung nach Absatz 4a war noch nicht Entscheidungsgegenstand.\n\nBeispiel: Eine Kammer will für ein Sachgebiet zusätzliche Qualifikationsnachweise einführen.')
change('p36a','Absatz 4 enthält Empfangs-, Entscheidungs- und Verlängerungsfristen sowie eine Hemmung bei Herkunftsnachfragen.','Absatz 4 verlangt innerhalb eines Monats eine Empfangsbestätigung und gegebenenfalls die Benennung fehlender Unterlagen. Die Dreimonatsfrist für den Abschluss des Anerkennungsverfahrens beginnt erst mit vollständigen Unterlagen; nur in begründeten Fällen ist ein weiterer Monat zulässig. Bei Echtheitszweifeln oder weiterem Informationsbedarf darf die Herkunftsstelle befragt werden; solange ist der Fristablauf gehemmt. Das ist keine voraussetzungslose Verlängerungsoption bei jeder internen Bearbeitungsverzögerung.')
all_diffs=[];changed=[]
for f in sorted((W/'commentary').glob('*.md')):
 s=f.read_text();before=s
 matches=list(re.finditer(r'^=== (\S+)\s*$',s,re.M))
 for m in reversed(matches):
  i=m.group(1)
  if i not in revisions:continue
  end=next((n.start() for n in matches if n.start()>m.start()),len(s));block=s[m.end():end]
  for a,b in revisions[i]:
   assert block.count(a)==1,(i,a[:100]);block=block.replace(a,b)
  s=s[:m.end()]+block+s[end:];changed.append(i)
 if s!=before:
  f.write_text(s);all_diffs+=list(difflib.unified_diff(before.splitlines(True),s.splitlines(True),fromfile='before/'+str(f.relative_to(W)),tofile='after/'+str(f.relative_to(W))))
(D/'commentary-changes.diff').write_text(''.join(all_diffs))
(D/'revisions.json').write_text(json.dumps({'reviewed_ids':IDS,'changed_ids':[i for i in IDS if i in changed],'unchanged_ids':[i for i in IDS if i not in changed]},indent=2)+'\n')
print((D/'revisions.json').read_text())
